select member_id || '|' || cast(month_start as varchar) as member_month_key, member_id, month_start, valid_order_count from (select member_id, cast(date_trunc('month', ordered_at) as date) as month_start, count(*) as valid_order_count from {{ ref('orders') }} where status = 'paid' and paid_cents - refund_cents > 0 group by member_id, cast(date_trunc('month', ordered_at) as date)) activity